using Intropy.Topology;
using Contracts;

/// <summary>
/// The system's messages, each defined once and shared by every component that touches it: the
/// seven tier 1 Ladok events with consumers, all on the ladok-events topic. The message name is
/// the CloudEvent type, as the xRegistry declares it. The extractor also mirrors every other Ladok
/// event on the same topic, under se.ladok.&lt;namespace&gt;.&lt;term&gt;; those have no consumer
/// and so no message here.
/// </summary>
public static class Messages
{
    private const string Topic = "ladok-events";

    public static readonly MessageRef<KurstillfalleKlarmarkerat> KurstillfalleKlarmarkerat =
        MessageRef<KurstillfalleKlarmarkerat>.Define("se.ladok.utbildning.kurstillfalle.klarmarkerat.v1", topic: Topic);

    public static readonly MessageRef<AntagningCreated> AntagningCreated =
        MessageRef<AntagningCreated>.Define("se.ladok.studiedeltagande.antagning.created.v1", topic: Topic);

    public static readonly MessageRef<RegistreringCreated> RegistreringCreated =
        MessageRef<RegistreringCreated>.Define("se.ladok.studiedeltagande.registrering.created.v1", topic: Topic);

    public static readonly MessageRef<OmregistreringCreated> OmregistreringCreated =
        MessageRef<OmregistreringCreated>.Define("se.ladok.studiedeltagande.omregistrering.created.v1", topic: Topic);

    public static readonly MessageRef<AntagningDeleted> AntagningDeleted =
        MessageRef<AntagningDeleted>.Define("se.ladok.studiedeltagande.antagning.deleted.v1", topic: Topic);

    public static readonly MessageRef<RegistreringDeleted> RegistreringDeleted =
        MessageRef<RegistreringDeleted>.Define("se.ladok.studiedeltagande.registrering.deleted.v1", topic: Topic);

    public static readonly MessageRef<OmregistreringDeleted> OmregistreringDeleted =
