using Intropy.Topology.Generation;

/// <summary>Local OpenAPI-backed substitutes for students.</summary>
public sealed class StudentsDevelopment : IDevelopmentDefinition
{
    /// <inheritdoc />
    public void Define(DevelopmentBuilder development)
    {
        development.Mock(Services.BusinessIncidents).FromOpenApi("mocks/business-incident-service.openapi.yaml");
        // Ladok's feed, generated by mocks/ladok-feed/generate.py and moved through demo steps
        // with `task feed:next`.
        development.Mock(Ports.LadokExtractorSource).FromOpenApi("mocks/ladok-feed.openapi.yaml");
        // Ladok's REST API (mocks/ladok-api/generate.py): six kurstillfällen, their utbildningstyper,
        // and a rate limit shared by every caller (`task ladok:rate-limit -- 1` tightens it).
        development.Mock(Ports.LadokApi).FromOpenApi("mocks/ladok-api.openapi.yaml");
        development.Rerun("ladok-extractor").AfterEachRun(TimeSpan.FromSeconds(30));
        // AD and IAM as folders: `task ad:seed` empties them; ad-group-loader creates the groups, and
        // the IAM mock (started by `task run`) turns account requests into AD accounts after a delay.
        development.Files(Ports.Ad).RootPath("./test/ad");
        development.Files(Ports.Iam).RootPath("./test/iam");
    }
}
